import { mergeProps } from '@base-ui/react/merge-props';
import { useRender } from '@base-ui/react/use-render';
import styles from './text.module.css.js';

function Text({ ref, render, ...props }) {
    return useRender({
        defaultTagName: 'p',
        render,
        ref,
        props: mergeProps({
            className: styles.text
        }, props)
    });
}

export { Text };
