import { mergeProps } from '@base-ui/react/merge-props';
import { useRender } from '@base-ui/react/use-render';
import styles from './inline-code.module.css.js';

/** Code within running text. Renders `code` by default. */ function InlineCode({ ref, render, variant = 'soft', ...props }) {
    return useRender({
        defaultTagName: 'code',
        render,
        ref,
        props: {
            ...mergeProps({
                className: styles.root
            }, props),
            'data-variant': variant
        }
    });
}

export { InlineCode };
